const seedRole = `-- name: SeedRole :one
INSERT INTO oikumenea.authz_roles (code, name, description, is_base)
SELECT $1, $2, $3, true
WHERE NOT EXISTS (
  SELECT 1 FROM oikumenea.authz_roles WHERE code = $1 AND deleted_at IS NULL
)
RETURNING id, code, name, description, is_base, created_at, updated_at
`

type SeedRoleParams struct {
	Code        string
	Name        string
	Description pgtype.Text
}

type SeedRoleRow struct {
	ID          string
	Code        string
	Name        string
	Description pgtype.Text
	IsBase      bool
	CreatedAt   pgtype.Timestamptz
	UpdatedAt   pgtype.Timestamptz
}

// Idempotent base-role seed (D-RIDSeeding): insert if the code is free among active rows, else
// return the existing row. ON CONFLICT needs the partial-unique index's predicate, which a plain
// ON CONFLICT cannot target, so we guard with WHERE NOT EXISTS and fall back to a select in the app.
func (q *Queries) SeedRole(ctx context.Context, arg SeedRoleParams) (SeedRoleRow, error) {
	row := q.db.QueryRow(ctx, seedRole, arg.Code, arg.Name, arg.Description)
	var i SeedRoleRow
	err := row.Scan(
		&i.ID,
		&i.Code,
		&i.Name,
		&i.Description,
		&i.IsBase,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

